-- SafetyTraining v20.064
-- Dirigente evidence enrichment batch 2: contractors, emergency coverage, competence chain, organizational integrity.
-- Creates draft v2; published v1 remains used by current course composition.

with base as (
 select lu.id learning_unit_id,lu.stable_key,v.content
 from public.learning_units lu
 join lateral (select content from public.learning_unit_versions luv where luv.learning_unit_id=lu.id and luv.status='published' order by version_number desc limit 1) v on true
 where lu.stable_key in ('dirigente:appalti-interferenze','dirigente:emergenze-organizzazione','dirigente:comunicazione-formazione-consultazione','dirigente:sistema-istituzionale-231-tutele')
), enriched as (
 select learning_unit_id,stable_key,
  content || jsonb_build_object('didactic_version','dirigente-evidence-v2','quality',coalesce(content->'quality','{}'::jsonb)||jsonb_build_object('teacher_ready',true,'learner_ready',true,'decision_based',true,'managerial_output_required',true),'source_audit',jsonb_build_object('status','reviewed','checked_on','2026-10-15','normative_validation','D.Lgs. 81/2008 vigente + ASR 17/04/2025','reuse_policy','reference_and_original_rewrite'),'evidence_sources',jsonb_build_array(jsonb_build_object('authority','Ministero del Lavoro e delle Politiche Sociali','title','Accordo Stato-Regioni 17 aprile 2025','url','https://lavoro.gov.it/temi-e-priorita/salute-e-sicurezza/focus/pagine/accordo-stato-regioni-del-17042025-materia-di-formazione','use','normative_validation','checked_on','2026-10-15'),jsonb_build_object('authority','Normattiva','title','D.Lgs. 81/2008 - testo vigente','url','https://www.normattiva.it/eli/id/2008/04/30/008G0104/CONSOLIDATED','use','normative_validation','checked_on','2026-10-15')))
  || case stable_key
   when 'dirigente:appalti-interferenze' then jsonb_build_object('contractor_change_control_lab',jsonb_build_object('title','Appalto: quando cambia una condizione, il coordinamento va riaperto','change_triggers',jsonb_build_array('anticipo/posticipo attività','cambio area o accessi','nuova impresa/subappaltatore','nuovi mezzi/sostanze/energie','sovrapposizione con attività interne','modifica del layout o delle vie di esodo','lavorazione non prevista','carenza di informazioni/permessi'),'board',jsonb_build_array('cambiamento','interferenza generata','chi è esposto','misura immediata','misura di coordinamento','soggetto responsabile','documento/procedura da aggiornare se necessario','briefing ai soggetti','evidenza prima della ripresa'),'scenario','La manutenzione viene anticipata e occupa la viabilità interna prevista per movimentazione. Il DUVRI originario non contempla la sovrapposizione: il dirigente deve decidere stop/riorganizzazione, coordinamento e verifica prima della ripresa.','anti_document_rule','Il DUVRI o il contratto non assorbono automaticamente un cambiamento reale: il sistema deve tornare coerente prima/proseguendo secondo condizioni controllate.'))
   when 'dirigente:emergenze-organizzazione' then jsonb_build_object('emergency_coverage_matrix',jsonb_build_object('title','Il piano regge davvero in ogni turno e configurazione?','dimensions',jsonb_build_array('turno/fascia oraria','presenze','addetti antincendio','addetti primo soccorso','competenze/abilitazioni pertinenti','layout/vie esodo','lavori temporanei/appaltatori','persone con esigenze specifiche','accesso soccorsi','sistemi temporaneamente indisponibili','misure compensative','responsabile della verifica'),'scenario','Turno serale con pochi addetti, manutentori esterni e via di esodo modificata: valutare se il piano resta attuabile e quali misure organizzative servono prima di proseguire.','managerial_test','Non basta che il numero di addetti sia corretto sulla carta: devono essere realmente presenti, distribuiti, informati e in grado di operare nel layout e nelle condizioni del turno.'),'drill_to_management_loop',jsonb_build_array('osserva la prova/evento','identifica criticità organizzative','assegna azioni','fornisci risorse','verifica chiusura','riprova/riesamina'))
   when 'dirigente:comunicazione-formazione-consultazione' then jsonb_build_object('decision_to_competence_lab',jsonb_build_object('title','Una comunicazione è completa solo quando cambia il comportamento atteso','chain',jsonb_build_array('decisione/cambiamento','destinatari','cosa devono sapere','cosa devono saper fare','strumento: informazione/formazione/addestramento/briefing','chi eroga','quando','come si verifica comprensione/competenza','come si osserva l’applicazione','feedback/correzione'),'scenario','Nuova procedura inviata via email; due reparti la interpretano diversamente. Il dirigente deve distinguere cosa richiede semplice comunicazione e cosa richiede formazione/addestramento/verifica sul campo.','consultation_gate',jsonb_build_array('il cambiamento tocca rischi/misure?','serve consultazione RLS secondo il quadro applicabile?','sono coinvolti preposti/RSPP/MC o altri soggetti?','chi raccoglie feedback e come viene chiuso?')),'anti_email_rule','Inviare un documento produce tracciabilità della trasmissione, non prova automaticamente comprensione, competenza o applicazione.')
   when 'dirigente:sistema-istituzionale-231-tutele' then jsonb_build_object('organizational_integrity_lab',jsonb_build_object('title','Carta vs realtà: stress test dell’organizzazione','tests',jsonb_build_array('chi riceve una segnalazione?','chi decide e con quale potere?','chi controlla che l’azione venga eseguita?','chi verifica l’efficacia?','come emergono near miss e non conformità?','come sono gestiti conflitti/interessi produttivi?','come vengono trattati molestie, violenze o comportamenti inaccettabili?','che cosa succede se un responsabile non agisce?'),'scenario','Organigramma e procedure formalmente corretti, ma i reparti descrivono processi diversi e le anomalie non hanno un owner chiaro. Il dirigente deve distinguere difetto documentale da difetto organizzativo e progettare la correzione.','required_output','Mappa di massimo cinque gap con rischio organizzativo, owner, azione, risorsa, scadenza ed evidenza di efficacia.'),'231_sgsl_boundary','MOG/SGSL e sistema 231 non si riducono alla presenza di procedure: la formazione manageriale deve verificare attribuzioni, flussi, controlli, gestione delle anomalie e funzionamento effettivo delle misure.','psychosocial_governance','Molestie, violenze e aggressioni vanno integrate nei processi di prevenzione quando pertinenti: canali, responsabilità, gestione degli eventi e misure organizzative devono essere chiari e verificabili.','evidence_sources',jsonb_build_array(jsonb_build_object('authority','INAIL','title','Sistemi di gestione della salute e sicurezza sul lavoro - SGSL','url','https://www.inail.it/portale/prevenzione-e-sicurezza/it/come-fare-per/migliorare-la-salute-e-la-sicurezza/sgsl.html','use','management_system_reference','checked_on','2026-10-15'),jsonb_build_object('authority','INAIL','title','Molestie e violenze sul lavoro - analisi e prevenzione','url','https://www.inail.it/portale/it/inail-comunica/news/notizia.2025.03.molestie-e-violenze-sul-lavoro-analisi-di-un-fenomeno-in-crescita.html','use','organizational_risk_reference','checked_on','2026-10-15')))
   end as new_content
 from base
)
insert into public.learning_unit_versions(learning_unit_id,version_number,status,content,content_hash,published_at)
select learning_unit_id,2,'draft',new_content,md5(new_content::text),null from enriched
on conflict (learning_unit_id,version_number) do update set status='draft',content=excluded.content,content_hash=excluded.content_hash,published_at=null;

insert into public.learning_unit_sources(learning_unit_id,source_key,purpose,relevance_note,verified_on,metadata)
select lu.id,'mlps-asr-2025','normative_validation','Fonte ufficiale MLPS dell’ASR 2025 per contenuti/obiettivi del corso dirigenti.',date '2026-10-15','{}'::jsonb from public.learning_units lu where lu.stable_key in ('dirigente:appalti-interferenze','dirigente:emergenze-organizzazione','dirigente:comunicazione-formazione-consultazione','dirigente:sistema-istituzionale-231-tutele')
on conflict (learning_unit_id,source_key,purpose) do update set relevance_note=excluded.relevance_note,verified_on=excluded.verified_on,metadata=excluded.metadata;
insert into public.learning_unit_sources(learning_unit_id,source_key,purpose,relevance_note,verified_on,metadata)
select lu.id,'normattiva-dlgs81-vigente','normative_validation','Validazione vigente per appalti/interferenze, emergenze, informazione/formazione/consultazione e organizzazione della prevenzione.',date '2026-10-15','{}'::jsonb from public.learning_units lu where lu.stable_key in ('dirigente:appalti-interferenze','dirigente:emergenze-organizzazione','dirigente:comunicazione-formazione-consultazione','dirigente:sistema-istituzionale-231-tutele')
on conflict (learning_unit_id,source_key,purpose) do update set relevance_note=excluded.relevance_note,verified_on=excluded.verified_on,metadata=excluded.metadata;
insert into public.learning_unit_sources(learning_unit_id,source_key,purpose,relevance_note,verified_on,metadata)
select lu.id,'inail-sgsl','management_system_reference','Riferimento INAIL per controllo dei processi, ruoli, flussi e miglioramento organizzativo.',date '2026-10-15','{}'::jsonb from public.learning_units lu where lu.stable_key='dirigente:sistema-istituzionale-231-tutele'
on conflict (learning_unit_id,source_key,purpose) do update set relevance_note=excluded.relevance_note,verified_on=excluded.verified_on,metadata=excluded.metadata;
insert into public.learning_unit_sources(learning_unit_id,source_key,purpose,relevance_note,verified_on,metadata)
select lu.id,'inail-violence-work-2025','organizational_risk_reference','Evidenze per integrare molestie, minacce e aggressioni nei processi di prevenzione e governance quando pertinenti.',date '2026-10-15','{}'::jsonb from public.learning_units lu where lu.stable_key='dirigente:sistema-istituzionale-231-tutele'
on conflict (learning_unit_id,source_key,purpose) do update set relevance_note=excluded.relevance_note,verified_on=excluded.verified_on,metadata=excluded.metadata;
insert into public.learning_unit_sources(learning_unit_id,source_key,purpose,relevance_note,verified_on,metadata)
select lu.id,'vvf-materiali-antincendio','technical_reference','Riferimento tecnico per organizzazione delle emergenze e verifica di coerenza fra piano, addetti e condizioni reali.',date '2026-10-15','{}'::jsonb from public.learning_units lu where lu.stable_key='dirigente:emergenze-organizzazione'
on conflict (learning_unit_id,source_key,purpose) do update set relevance_note=excluded.relevance_note,verified_on=excluded.verified_on,metadata=excluded.metadata;
